\begin{exercise}\label{exercise:11.23}
对\hyperref[sec:11.5.3]{杂录11.5.3}的模型：
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.23.a} 证明$Y_{ij}$的均值、方差为$EY_{ij}=\mu+\tau_i$和$\operatorname{Var}Y_{ij}=\sigma_B^2+\sigma^2$.
\item\label{item:11.23.b} 若$\sum a_i=0$，证明$\sum a_i\bar Y_{i\cdot}$的无条件方差为
$$\operatorname{Var}\left(\sum a_i\bar Y_{i\cdot}\right)=\frac1r(\sigma^2+\sigma_B^2)(1-\rho)\sum a_i^2,$$
其中$\rho$为组内相关系数.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.24}
\hyperref[sec:11.5.6]{杂录11.5.6}的Stein估计量形式，可以通过\hyperref[bib:source111]{Efron和Morris（1972）}给出的经验贝叶斯论证得到一定解释，该论证在数据分析中相当有用. \hyperref[bib:source301]{Stein（1956）}可能已经知道这样的论证，但未提及. 设$X_i\sim\mathrm n(\theta_i,1)$，$i=1,\ldots,p$，且$\theta_i$独立同分布于$\mathrm n(0,\tau^2)$.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.24.a} 证明$X_i$的边缘分布独立同为$\mathrm n(0,\tau^2+1)$，从而$\sum X_i^2/(\tau^2+1)\sim\chi^2_p$.

491.text:
\item\label{item:11.24.b} 利用边缘分布，证明若$p\ge3$，则
$$E\left(1-\frac{p-2}{\sum_{j=1}^pX_j^2}\right)=\frac{\tau^2}{\tau^2+1}.$$
因此，\hyperref[sec:11.5.6]{杂录11.5.6}的Stein估计量是贝叶斯估计量$\delta_\pi^i(\boldsymbol X)=[\tau^2/(\tau^2+1)]X_i$的经验贝叶斯版本.
\item\label{item:11.24.c} 证明：若$Y\sim\chi^2_p$且$p<3$，则$E(1/Y)=\infty$，从而说明$p<3$时该论证失效.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.25}
\autoref{sec:11.3.1}通过两阶段最小化求出了$\alpha,\beta$的最小二乘估计. 这个最小化也可用偏导数进行.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.25.a} 计算$\partial\mathrm{RSS}/\partial c$和$\partial\mathrm{RSS}/\partial d$，并令其为零. 证明所得两个方程可写成
$$nc+\left(\sum_{i=1}^nx_i\right)d=\sum_{i=1}^ny_i,
\qquad
\left(\sum_{i=1}^nx_i\right)c+\left(\sum_{i=1}^nx_i^2\right)d=\sum_{i=1}^nx_iy_i.$$
（这些方程称为该最小化问题的正规方程，normal equations.）
\item\label{item:11.25.b} 证明$c=a$和$d=b$是正规方程的解.
\item\label{item:11.25.c} 检查二阶偏导数条件，验证$c=a,d=b$这一点确实使RSS最小.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.26}
假设$n$为偶数. 预测变量的值$x_1,\ldots,x_n$都必须在区间$[e,f]$中选取. 证明，使$S_{xx}$最大的选择，是令一半$x_i$等于$e$，另一半等于$f$. （这是\autoref{sec:11.3.2}中提到的使$\operatorname{Var}b$最小的选择.）
\end{exercise}

\begin{exercise}\label{exercise:11.27}
观测$(x_i,Y_i)$，$i=1,\ldots,n$，服从模型$Y_i=\alpha+\beta x_i+\varepsilon_i$，其中$E\varepsilon_i=0$、$\operatorname{Var}\varepsilon_i=\sigma^2$，且$i\ne j$时$\operatorname{Cov}(\varepsilon_i,\varepsilon_j)=0$. 求$\alpha$的最优线性无偏估计量.
\end{exercise}

\begin{exercise}\label{exercise:11.28}
证明，在简单线性回归的条件正态模型中，$\sigma^2$的MLE为
$$\hat\sigma^2=\frac1n\sum_{i=1}^n(y_i-\hat\alpha-\hat\beta x_i)^2.$$
\end{exercise}

\begin{exercise}\label{exercise:11.29}
考虑\autoref{sec:11.3.4}中由$\hat\varepsilon_i=Y_i-\hat\alpha-\hat\beta x_i$定义的残差$\hat\varepsilon_1,\ldots,\hat\varepsilon_n$.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.29.a} 证明$E\hat\varepsilon_i=0$.
\item\label{item:11.29.b} 验证
$$\begin{aligned}
\operatorname{Var}\hat\varepsilon_i
={}&\operatorname{Var}Y_i+\operatorname{Var}\hat\alpha+x_i^2\operatorname{Var}\hat\beta
-2\operatorname{Cov}(Y_i,\hat\alpha)\\
&-2x_i\operatorname{Cov}(Y_i,\hat\beta)+2x_i\operatorname{Cov}(\hat\alpha,\hat\beta).
\end{aligned}$$
\item\label{item:11.29.c} 用\autoref{lem:11.3.2}证明
$$\operatorname{Cov}(Y_i,\hat\alpha)=\sigma^2\left(\frac1n+\frac{(x_i-\bar x)\bar x}{S_{xx}}\right)
\quad\text{且}\quad\operatorname{Cov}(Y_i,\hat\beta)=\sigma^2\frac{x_i-\bar x}{S_{xx}},$$
并用它们验证\eqref{eq:11.3.28}.\footnote{译注：第一个协方差式中的加号应为减号，由$\hat\alpha=\sum_i[1/n-(x_i-\bar x)\bar x/S_{xx}]Y_i$可直接核对. 原题照录.}
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.30}
补全\autoref{thm:11.3.3}证明中略去的关于$\hat\alpha$分布的细节.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.30.a} 证明估计量$\hat\alpha=\bar y-\hat\beta\bar x$可表示为$\hat\alpha=\sum_{i=1}^nc_iY_i$，其中
$$c_i=\frac1n-\frac{(x_i-\bar x)\bar x}{S_{xx}}.$$
\item\label{item:11.30.b} 验证
$$E\hat\alpha=\alpha\quad\text{且}\quad\operatorname{Var}\hat\alpha=\sigma^2\left[\frac1{nS_{xx}}\sum_{i=1}^nx_i^2\right].$$
\item\label{item:11.30.c} 验证
$$\operatorname{Cov}(\hat\alpha,\hat\beta)=-\frac{\sigma^2\bar x}{S_{xx}}.$$
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.31}
验证\autoref{thm:11.3.3}中的断言：$\hat\varepsilon_i$与$\hat\alpha,\hat\beta$互不相关. （证明$\hat\varepsilon_i=\sum e_jY_j$，其中$e_j$由\eqref{eq:11.3.30}给出. 再利用$\hat\alpha=\sum c_jY_j$和$\hat\beta=\sum d_jY_j$，验证$\sum e_jc_j=\sum e_jd_j=0$，并应用\autoref{lem:11.3.2}.）
\end{exercise}

492.text:
\begin{exercise}\label{exercise:11.32}
按照模型
$$Y_i=\alpha+\beta x_i+\varepsilon_i$$
取得观测$(x_i,Y_i)$，$i=1,\ldots,n$，其中$x_1,\ldots,x_n$为固定常数，$\varepsilon_1,\ldots,\varepsilon_n$独立同分布于$\mathrm n(0,\sigma^2)$. 将模型重新参数化为
$$Y_i=\alpha'+\beta'(x_i-\bar x)+\varepsilon_i.$$
设$\hat\alpha,\hat\beta$分别为$\alpha,\beta$的MLE，$\hat\alpha',\hat\beta'$分别为$\alpha',\beta'$的MLE.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.32.a} 证明$\hat\beta'=\hat\beta$.
\item\label{item:11.32.b} 证明$\hat\alpha'\ne\hat\alpha$. 事实上，证明$\hat\alpha'=\bar Y$. 求$\hat\alpha'$的分布.\footnote{译注：原题不等号应理解为两个估计量一般不同；若$\bar x=0$，二者相同，个别样本也可能取相同值. 原文保留.}
\item\label{item:11.32.c} 证明$\hat\alpha',\hat\beta'$互不相关，从而在正态性下独立.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.33}
从参数为$(\mu_X,\mu_Y,\sigma_X^2,\sigma_Y^2,\rho)$的二元正态总体取得观测$(X_i,Y_i)$，$i=1,\ldots,n$，拟合模型$Y_i=\alpha+\beta x_i+\varepsilon_i$.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.33.a} 说明假设$H_0:\beta=0$成立当且仅当假设$H_0:\rho=0$成立. （见\eqref{eq:11.3.25}.）
\item\label{item:11.33.b} 用代数方法证明
$$\frac{\hat\beta}{S/\sqrt{S_{xx}}}=\sqrt{n-2}\frac r{\sqrt{1-r^2}},$$
其中$r$为样本相关系数，也是$\rho$的MLE.
\item\label{item:11.33.c} 说明如何只给定$r^2$和$n$，使用自由度为$n-2$的Student $t$分布检验$H_0:\rho=0$（见\eqref{eq:11.3.33}）. （Fisher利用方差稳定变换推导了$\rho$的近似置信区间，见\autoref{exercise:11.4}.）
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.34}
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.34.a} 计算下列数据的回归ANOVA表，说明简单线性回归的平方和分解. 父母常希望预测孩子成年后的身高. 以下数据来自一项可能受到Galton分析启发的研究，是其中的一部分.
\begin{center}
\begin{tabular}{lrrrrrrrr}
\toprule 两岁身高（英寸）（$x$）&39&30&32&34&35&36&36&30\\\midrule
成年身高（英寸）（$y$）&71&63&63&67&68&68&70&64\\\bottomrule
\end{tabular}
\end{center}
\item\label{item:11.34.b} 验证\eqref{eq:11.3.36}，从解析上建立简单线性回归的平方和分解.
\item\label{item:11.34.c} 证明回归平方和的两个表达式确实相等，即
$$\sum_{i=1}^n(\hat y_i-\bar y)^2=\frac{S_{xy}^2}{S_{xx}}.$$
\item\label{item:11.34.d} 证明决定系数
$$r^2=\frac{\sum_{i=1}^n(\hat y_i-\bar y)^2}{\sum_{i=1}^n(y_i-\bar y)^2}$$
既可以推导为$n$对$(y_1,x_1),\allowbreak\ldots,\allowbreak(y_n,x_n)$的样本相关系数平方，也可以推导为$n$对$(y_1,\hat y_1),\allowbreak\ldots,\allowbreak(y_n,\hat y_n)$的样本相关系数平方.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.35}
观测$Y_1,\ldots,Y_n$由关系$Y_i=\theta x_i^2+\varepsilon_i$描述，其中$x_1,\ldots,x_n$为固定常数，$\varepsilon_1,\ldots,\varepsilon_n$独立同分布于$\mathrm n(0,\sigma^2)$.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.35.a} 求$\theta$的最小二乘估计量.
\item\label{item:11.35.b} 求$\theta$的MLE.
\item\label{item:11.35.c} 求$\theta$的最优无偏估计量.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.36}
按照模型$Y_i=\alpha+\beta x_i+\varepsilon_i$观测$Y_1,\ldots,Y_n$，其中$x_1,\ldots,x_n$为固定常数，$\varepsilon_1,\ldots,\varepsilon_n$独立同分布于$\mathrm n(0,\sigma^2)$. 设$\hat\alpha,\hat\beta$为$\alpha,\beta$的MLE.

493.text:
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.36.a} 假设$x_1,\ldots,x_n$是独立同分布随机变量$X_1,\ldots,X_n$的观测值，其分布为$\mathrm n(\mu_X,\sigma_X^2)$. 证明，对$X,Y$的联合分布取期望时，仍有$E\hat\alpha=\alpha$和$E\hat\beta=\beta$.
\item\label{item:11.36.b} \hyperref[item:11.36.a]{(a)}的现象不能推广到协方差. 利用$X,Y$的联合分布，计算$\hat\alpha,\hat\beta$的无条件协方差.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.37}
观测随机变量$Y_1,\ldots,Y_n$，它们相互独立，各服从方差为$\sigma^2$的正态分布. 此外，$EY_i=\beta x_i$，其中$\beta$为未知参数，$x_1,\ldots,x_n$为不全为零的固定常数.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.37.a} 求$\beta$的MLE，并计算其均值和方差.
\item\label{item:11.37.b} 计算$\beta$的无偏估计量方差的Cram\'er--Rao下界.
\item\label{item:11.37.c} 求$\beta$的最优无偏估计量.
\item\label{item:11.37.d} 若可将$x_1,\ldots,x_n$放在给定非退化闭区间$[A,B]$内任意位置，应如何放置？说明理由.
\item\label{item:11.37.e} 对给定正数$r$，$\beta$关于$r$的最大概率估计量（maximum probability estimator）是使积分
$$\int_{D-r}^{D+r}f(y_1,\ldots,y_n\mid\beta)\,d\beta$$
最大的$D$值，其中$f(y_1,\ldots,y_n\mid\beta)$是$Y_1,\ldots,Y_n$的联合pdf. 求此估计量.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:11.38}
一位生态学家取得数据$(x_i,Y_i)$，$i=1,\ldots,n$，其中$x_i$为区域面积，$Y_i$为该区域的苔藓植株数. 用模型$Y_i\sim\operatorname{Poisson}(\theta x_i)$描述数据，各$Y_i$独立.
\begin{enumerate}[label=(\alph*)]
\item\label{item:11.38.a} 证明$\theta$的最小二乘估计量为$\sum x_iY_i/\sum x_i^2$. 证明它的方差为$\theta\sum x_i^3/(\sum x_i^2)^2$，并计算其偏倚.
\item\label{item:11.38.b} 证明$\theta$的MLE为$\sum Y_i/\sum x_i$，方差为$\theta/\sum x_i$. 计算其偏倚.
\item\label{item:11.38.c} 求$\theta$的最优无偏估计量，并证明其方差达到Cram\'er--Rao下界.
\end{enumerate}
\end{exercise}

