\item\label{item:12.8.b} 证明至少存在两个不同的参数向量，对\eqref{eq:12.2.20}的方程给出相同的解.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:12.9}
结构关系模型中，\eqref{eq:12.2.20}的解对$\hat\beta$施加一个限制，与函数关系情形的限制相同（\autoref{exercise:12.4}）.
\begin{enumerate}[label=(\alph*)]
\item\label{item:12.9.a} 证明\eqref{eq:12.2.20}中，$\sigma_\delta^2$的MLE非负仅当$S_{xx}\ge(1/\hat\beta)S_{xy}$；$\sigma_\varepsilon^2$的MLE非负仅当$S_{yy}\ge\hat\beta S_{xy}$.
\item\label{item:12.9.b} 证明\hyperref[item:12.9.a]{(a)}的限制与\eqref{eq:12.2.20}其余方程共同推出
$$\frac{|S_{xy}|}{S_{xx}}\le|\hat\beta|\le\frac{S_{yy}}{|S_{xy}|}.$$
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:12.10}
\begin{enumerate}[label=(\alph*)]
\item\label{item:12.10.a} 假设$\sigma_\delta^2=\lambda\sigma_\varepsilon^2$，解\eqref{eq:12.2.20}，推导结构关系模型中$(\alpha,\beta,\sigma_\varepsilon^2,\sigma_\delta^2,\sigma_\xi^2)$的MLE.
\item\label{item:12.10.b} 假设结构关系模型成立且$\sigma_\delta^2=\lambda\sigma_\varepsilon^2$，计算\autoref{exercise:12.4}数据的$(\alpha,\beta,\sigma_\varepsilon^2,\sigma_\delta^2,\sigma_\xi^2)$的MLE.
\item\label{item:12.10.c} 验证函数关系模型与结构关系模型中方差估计的关系. 特别地，证明
$$\widehat{\operatorname{Var}}X_i(\text{结构})=2\widehat{\operatorname{Var}}X_i(\text{函数}).$$
即验证\footnote{译注：后一等式比较的是两模型中的测量误差方差$\sigma_\delta^2$估计；结构模型的无条件$\operatorname{Var}X_i=\sigma_\delta^2+\sigma_\xi^2$，故前一式的方差名称易造成混淆. 原题保留.}
$$\left(S_{xx}-\frac{S_{xy}}{\hat\beta}\right)=\frac\lambda{1+\lambda\hat\beta^2}\sum_{i=1}^n\bigl(y_i-(\hat\alpha+\hat\beta x_i)\bigr)^2.$$
\item\label{item:12.10.d} 验证\eqref{eq:12.2.21}的MLE方差估计中隐含的等式：
$$S_{xx}-\frac{S_{xy}}{\hat\beta}=\lambda(S_{yy}-\hat\beta S_{xy}).$$
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:12.11}
\begin{enumerate}[label=(\alph*)]
\item\label{item:12.11.a} 证明对随机变量$X,Y$和常数$a,b,c,d$，
$$\operatorname{Cov}(aY+bX,cY+dX)=ac\operatorname{Var}Y+(bc+ad)\operatorname{Cov}(X,Y)+bd\operatorname{Var}X.$$
\item\label{item:12.11.b} 用\hyperref[item:12.11.a]{(a)}验证，在$\sigma_\delta^2=\lambda\sigma_\varepsilon^2$的结构关系模型中，
$$\operatorname{Cov}(\beta\lambda Y_i+X_i,Y_i-\beta X_i)=0,$$
这就是Creasy--Williams置信集所依据的恒等式.

521.text:
\item\label{item:12.11.c} 用\hyperref[item:12.11.b]{(b)}证明，对任意$\beta$，
$$\frac{\sqrt{n-2}\,r_\lambda(\beta)}{\sqrt{1-r_\lambda^2(\beta)}}\sim t_{n-2},$$
其中$r_\lambda(\beta)$由\eqref{eq:12.2.23}给出. 再证明\eqref{eq:12.2.24}定义的置信集具有恒定覆盖概率$1-\alpha$.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:12.12}
验证关于$\hat\beta$（假设$\sigma_\delta^2=\lambda\sigma_\varepsilon^2$时$\beta$的MLE）、\eqref{eq:12.2.23}的$r_\lambda(\beta)$以及\eqref{eq:12.2.24}的Creasy--Williams置信集$C_\lambda(\hat\beta)$的下列事实.
\begin{enumerate}[label=(\alph*)]
\item\label{item:12.12.a} $\hat\beta$与$-1/(\lambda\hat\beta)$是定义似然函数\eqref{eq:12.2.14}一阶导数零点的二次方程的两个根.
\item\label{item:12.12.b} 对每个$\beta$，$r_\lambda(\beta)=-r_\lambda(-1/(\lambda\beta))$.
\item\label{item:12.12.c} 若$\beta\in C_\lambda(\hat\beta)$，则$-1/(\lambda\beta)\in C_\lambda(\hat\beta)$.
\end{enumerate}
\end{exercise}

\begin{exercise}\label{exercise:12.13}
\eqref{eq:12.2.24}的Creasy--Williams置信集与\eqref{eq:12.2.22}的区间$C_G(\hat\beta)$之间有一个有趣联系.
\begin{enumerate}[label=(\alph*)]
\item\label{item:12.13.a} 证明
$$C_G(\hat\beta)=\left\{\beta:\frac{(\beta-\hat\beta)^2}{\hat\sigma_\beta^2/(n-2)}\le F_{1,n-2,\alpha}\right\},$$
其中$\hat\beta$是$\beta$的MLE，$\hat\sigma_\beta^2$是先前定义的$\sigma_\beta^2$的相合估计量.
\item\label{item:12.13.b} 证明Creasy--Williams集合可写为
$$\left\{\beta:\frac{(\beta-\hat\beta)^2}{\hat\sigma_\beta^2/(n-2)}
\left[\frac{(1+\lambda\beta\hat\beta)^2}{(1+\lambda\beta^2)^2}\right]\le F_{1,n-2,\alpha}\right\}.$$
因此，将方括号中的项替换为其概率极限1，即得到$C_G(\hat\beta)$. （推导这一表示时，$\hat\beta$与$-1/(\lambda\hat\beta)$是$r_\lambda(\beta)$分子的根这一事实很有帮助. 特别地，容易建立
$$\frac{r_\lambda^2(\beta)}{1-r_\lambda^2(\beta)}
=\frac{\lambda^2S_{xy}^2(\beta-\hat\beta)^2(\beta+(1/\lambda\hat\beta))^2}
{(1+\lambda\beta^2)^2(S_{xx}S_{yy}-S_{xy}^2)}.\quad\text{）}$$
\end{enumerate}
\end{exercise}

